// Spoken lines (docs/plan.md Phase 52, "What is spoken" and "How it plays"):
// a game's lines spoken in their speakers' voices, generated by a game
// app's voice engine (render/voiceclient.ts) and played by the sound
// (render/audio.ts) through the Voice group exactly as a recorded voice
// line is.
//
// What is spoken (`spokenLine`): with spoken lines on and the engine ready,
// an item with text that is not blank, no recorded `audio.voice` (a
// recorded line always wins), and a voice: its speaker's in `voices`, or,
// with no speaker (absent or empty), the `narrator`. A thought is spoken in
// its speaker's voice. The text goes as written; the speaker's name is not
// spoken.
//
// What is asked for (`createSpokenLines`): on each arrival the director
// applies with its voice (render/audiorules.ts: a read at once, a walk or a
// jump after its rest, a skip where it stops), the item's line at the top
// priority and the next `LINES_AHEAD` lines along the reading path below
// it, in story order as the sound's warm-up looks ahead (render/audio.ts
// `upcomingSoundFiles`: a route's start is a guess); lines the reader moved
// past or jumped away from are dropped (`planSpeech`). Each voice is
// registered once while the engine is ready, from its reference clip's
// bytes, the first time one of its lines is asked for. Generated lines are
// decoded and kept, least recently used first, under `SPOKEN_CAP_BYTES`,
// keyed by voice and text, so a line met again plays at once.
//
// How it plays: a line ready on arrival plays then; one that comes later
// plays when it comes if the reader is still on its item. Auto-forward
// waits for it: up to `SPOKEN_WAIT_MS` from arrival while it is generated,
// then until its end, measured from when it starts to play (and from each
// restart after a menu or a hidden page held it); a line that fails gives
// the hold up, and the item's text hold applies (machine.ts
// `setSpokenHold`). Turning spoken lines off, or the engine leaving ready,
// stops the line and drops every request. Turned on again, or ready again,
// the item on show is asked for as on an arrival.

import type { Item, Manifest, ManifestVoice } from "../machine/types";
import { type Decoded, decodedBytes } from "./audiocache";
import type { VoiceClient } from "./voiceclient";

/** The voices a game casts (`Manifest.voices` and `narrator`). */
export type Cast = Pick<Manifest, "voices" | "narrator">;

/** The narrator's voice key; a speaker's is `speaker:<name>`. */
const NARRATOR = "narrator";

/** One line to speak. */
export interface SpokenLine {
  /** The voice: `speaker:<name>` or `narrator`. */
  readonly voice: string;
  /** The item's text, as written. */
  readonly text: string;
  /** What the line is cached and asked for by: voice and text. */
  readonly key: string;
}

/** How many lines past the current one are asked for. */
export const LINES_AHEAD = 3;
/** How many items past the current one `linesAhead` looks through. */
export const AHEAD_SCAN = 12;
/** The current line's priority when nothing else is asked for. */
export const TOP_PRIORITY = 3;
/** How long auto-forward waits from arrival for a line being generated. */
export const SPOKEN_WAIT_MS = 20_000;
/**
 * The most decoded generated audio kept (bytes): at 48 kHz mono, about
 * 170 s of speech, some forty lines; a line met again past that is asked
 * for again (the helper's disk cache answers it at once).
 */
export const SPOKEN_CAP_BYTES = 32 * 1024 * 1024;

/** Whether a game casts any voice. */
export function hasVoices(cast: Cast): boolean {
  return (
    cast.narrator !== undefined ||
    (cast.voices !== undefined && Object.keys(cast.voices).length > 0)
  );
}

/** The voice a key names, if the game casts it. */
export function castVoice(
  cast: Cast,
  voice: string,
): ManifestVoice | undefined {
  if (voice === NARRATOR) return cast.narrator;
  if (!voice.startsWith("speaker:")) return undefined;
  const name = voice.slice("speaker:".length);
  const voices = cast.voices ?? {};
  return Object.keys(voices).includes(name) ? voices[name] : undefined;
}

/** A reference clip's format: its extension, lower case, without the dot. */
export function clipFormat(file: string): string {
  const name = file.slice(file.lastIndexOf("/") + 1);
  const dot = name.lastIndexOf(".");
  return dot < 0 ? "" : name.slice(dot + 1).toLowerCase();
}

/**
 * The line `item` speaks, or null (see the header). `active`: spoken lines
 * are on and the engine is ready.
 */
export function spokenLine(
  item: Item | undefined,
  cast: Cast,
  active: boolean,
): SpokenLine | null {
  if (!active || item === undefined) return null;
  const text = item.text;
  if (text === undefined || text.trim() === "") return null;
  if (item.audio?.voice !== undefined) return null;
  const speaker = item.speaker;
  const voice =
    speaker === undefined || speaker === "" ? NARRATOR : `speaker:${speaker}`;
  if (castVoice(cast, voice) === undefined) return null;
  return { voice, text, key: `${voice}\n${text}` };
}

/**
 * The items of the next `count` spoken lines after `cursor`, in story
 * order, looking through at most `scan` items.
 */
export function linesAhead(
  items: readonly Item[],
  cursor: number,
  cast: Cast,
  active: boolean,
  count = LINES_AHEAD,
  scan = AHEAD_SCAN,
): number[] {
  const found: number[] = [];
  if (!active) return found;
  const end = Math.min(items.length, cursor + 1 + scan);
  for (let i = cursor + 1; i < end && found.length < count; i += 1) {
    if (spokenLine(items[i], cast, true) !== null) found.push(i);
  }
  return found;
}

/**
 * What to ask for and drop, given the lines wanted now (by key, the current
 * line first, then the lines ahead in order; none cached) and the priority
 * of each line already asked for. A line no longer wanted is dropped. Each
 * wanted line must be asked for below the one before it: one already asked
 * for that is keeps its priority; one asked for above a line before it is
 * dropped and asked for again; a new one goes just below the line before
 * it, and a new current line above every line still asked for (at least
 * `TOP_PRIORITY`). So reading on keeps every request already made, and the
 * line the reader reaches next is always generated first.
 */
export function planSpeech(
  wanted: readonly string[],
  outstanding: ReadonlyMap<string, number>,
): {
  speak: { key: string; priority: number }[];
  drop: string[];
} {
  const keep = new Set(wanted);
  const drop = [...outstanding.keys()].filter((key) => !keep.has(key));
  let top = TOP_PRIORITY;
  for (const key of wanted) {
    const p = outstanding.get(key);
    if (p !== undefined) top = Math.max(top, p + 1);
  }
  const speak: { key: string; priority: number }[] = [];
  let ceiling = Number.POSITIVE_INFINITY;
  for (const key of wanted) {
    const p = outstanding.get(key);
    if (p !== undefined && p < ceiling) {
      ceiling = p;
      continue;
    }
    if (p !== undefined) drop.push(key);
    const priority = ceiling === Number.POSITIVE_INFINITY ? top : ceiling - 1;
    speak.push({ key, priority });
    ceiling = priority;
  }
  return { speak, drop };
}

/** A decoded line: its length in seconds, and its size for the cap. */
export interface SpokenBuffer extends Decoded {
  readonly duration: number;
}

export interface SpokenOptions<B extends SpokenBuffer> {
  items: readonly Item[];
  cast: Cast;
  client: Pick<
    VoiceClient,
    "status" | "subscribe" | "register" | "speak" | "drop"
  >;
  /** The Spoken lines setting at mount. */
  on: boolean;
  /** A reference clip's bytes, base64 (its `<file>.js` script). */
  clip(file: string): Promise<string>;
  /** A generated WAV (base64), decoded. */
  decode(wav: string): Promise<B>;
  /** Page time, as `Date.now()` (the machine's clock). */
  now(): number;
  /** machine.setSpokenHold. */
  hold(index: number, untilMs: number | null): void;
  /** Play `buffer` as item `index`'s voice line. */
  play(index: number, buffer: B): void;
  /** Stop the spoken line playing, if one is. */
  stop(): void;
  /** The buffer the voice plays now, which the cache never drops. */
  playing(): B | null;
  capBytes?: number;
}

export interface SpokenLines<B extends SpokenBuffer> {
  /** The director applied item `index` with its voice: an arrival. */
  arrive(index: number): void;
  /** The reader left the item (its voice stops). */
  leave(): void;
  /** Item `index`'s line started to play, with `remaining` seconds to go. */
  started(index: number, remaining: number): void;
  /** The Spoken lines setting changed. */
  setOn(on: boolean): void;
  /** Item `index`'s generated line, when it is kept. */
  cached(index: number): B | undefined;
  destroy(): void;
}

/** One line asked for. */
interface Request {
  readonly priority: number;
  /** The client's id once sent; null while its voice registers. */
  id: string | null;
  cancelled: boolean;
}

export function createSpokenLines<B extends SpokenBuffer>(
  options: SpokenOptions<B>,
): SpokenLines<B> {
  const { items, cast, client } = options;
  const capBytes = options.capBytes ?? SPOKEN_CAP_BYTES;
  let on = options.on;
  /** The item the reader is on (arrived, not left), and its line. */
  let wanted: {
    index: number;
    line: SpokenLine | null;
    played: boolean;
  } | null = null;
  const outstanding = new Map<string, Request>();
  /** Each voice's registration while the engine is ready. */
  const voiceIds = new Map<string, Promise<string>>();
  /** Decoded lines, least recently used first. */
  const cache = new Map<string, B>();
  let cachedBytes = 0;

  const ready = (): boolean => client.status()?.state === "ready";
  const isActive = (): boolean => on && ready();
  let active = isActive();

  function put(key: string, buffer: B): void {
    const old = cache.get(key);
    if (old !== undefined) {
      cache.delete(key);
      cachedBytes -= decodedBytes(old);
    }
    cache.set(key, buffer);
    cachedBytes += decodedBytes(buffer);
    const held = options.playing();
    for (const [other, kept] of cache) {
      if (cachedBytes <= capBytes) break;
      if (kept === held) continue;
      cache.delete(other);
      cachedBytes -= decodedBytes(kept);
    }
  }

  function voiceId(voice: string): Promise<string> {
    const known = voiceIds.get(voice);
    if (known !== undefined) return known;
    const clip = castVoice(cast, voice);
    const id =
      clip === undefined
        ? Promise.reject(new Error(`no voice ${voice}`))
        : options
            .clip(clip.file)
            .then((data) =>
              client.register(data, clipFormat(clip.file), clip.text),
            );
    id.catch(() => undefined); // its lines report it
    voiceIds.set(voice, id);
    return id;
  }

  function start(w: NonNullable<typeof wanted>, buffer: B): void {
    w.played = true;
    options.play(w.index, buffer);
  }

  function ask(line: SpokenLine, priority: number): void {
    const req: Request = { priority, id: null, cancelled: false };
    outstanding.set(line.key, req);
    const done = (): boolean => {
      if (outstanding.get(line.key) === req) outstanding.delete(line.key);
      return !req.cancelled;
    };
    voiceId(line.voice)
      .then((id) => {
        if (req.cancelled) return null;
        const asked = client.speak(id, line.text, priority);
        req.id = asked.id;
        return asked.result;
      })
      .then((speech) => (speech === null ? null : options.decode(speech.wav)))
      .then(
        (buffer) => {
          if (buffer === null) return;
          done();
          put(line.key, buffer);
          const w = wanted;
          if (w !== null && !w.played && w.line?.key === line.key) {
            start(w, buffer);
          }
        },
        () => {
          if (!done()) return;
          const w = wanted;
          // The line on show failed: auto-forward stops waiting for it.
          if (w !== null && !w.played && w.line?.key === line.key) {
            options.hold(w.index, null);
          }
        },
      );
  }

  function cancel(key: string): void {
    const req = outstanding.get(key);
    if (req === undefined) return;
    outstanding.delete(key);
    req.cancelled = true;
    if (req.id !== null) client.drop(req.id);
  }

  function dropAll(): void {
    for (const key of [...outstanding.keys()]) cancel(key);
  }

  /** Asks for the current line and those ahead, dropping the rest. */
  function plan(): void {
    if (!active) {
      dropAll();
      return;
    }
    const keys: string[] = [];
    const lines = new Map<string, SpokenLine>();
    const add = (line: SpokenLine | null): void => {
      if (line === null || cache.has(line.key) || lines.has(line.key)) return;
      keys.push(line.key);
      lines.set(line.key, line);
    };
    if (wanted !== null) {
      add(wanted.line);
      for (const i of linesAhead(items, wanted.index, cast, true)) {
        add(spokenLine(items[i], cast, true));
      }
    }
    const asked = new Map(
      [...outstanding].map(([key, req]) => [key, req.priority] as const),
    );
    const { speak, drop } = planSpeech(keys, asked);
    for (const key of drop) cancel(key);
    for (const { key, priority } of speak) {
      const line = lines.get(key);
      if (line !== undefined) ask(line, priority);
    }
  }

  /** The reader is on item `wanted.index`: its line, at once or asked for. */
  function want(w: NonNullable<typeof wanted>): void {
    const line = spokenLine(items[w.index], cast, true);
    w.line = line;
    w.played = false;
    if (line !== null) {
      options.hold(w.index, options.now() + SPOKEN_WAIT_MS);
      const kept = cache.get(line.key);
      if (kept !== undefined) {
        put(line.key, kept); // a use: the most recent now
        start(w, kept);
      }
    }
    plan();
  }

  /** Spoken lines became active or stopped being so. */
  function follow(): void {
    if (!ready()) voiceIds.clear();
    const now = isActive();
    if (now === active) return;
    active = now;
    if (active) {
      if (wanted !== null) want(wanted);
      return;
    }
    dropAll();
    const w = wanted;
    if (w?.line != null) {
      if (w.played) options.stop();
      options.hold(w.index, null);
      w.line = null;
      w.played = false;
    }
  }

  const unsubscribe = client.subscribe(follow);

  return {
    arrive(index) {
      if (wanted?.index === index) return; // applied again: already its own
      wanted = { index, line: null, played: false };
      if (active) want(wanted);
    },
    leave() {
      const w = wanted;
      wanted = null;
      if (w?.line != null) options.hold(w.index, null);
    },
    started(index, remaining) {
      if (wanted?.index !== index || wanted.line === null) return;
      options.hold(index, options.now() + remaining * 1000);
    },
    setOn(next) {
      on = next;
      follow();
    },
    cached(index) {
      const line = spokenLine(items[index], cast, true);
      return line === null ? undefined : cache.get(line.key);
    },
    destroy() {
      unsubscribe();
      dropAll();
      cache.clear();
      cachedBytes = 0;
      wanted = null;
    },
  };
}
